INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
(gen_random_uuid(), 'e5700001-5701-4570-8570-570157015701', 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Rangkaian Berperilaku Aneh Tanpa Kapasitor$txt$)),
(gen_random_uuid(), 'e5700001-5701-4570-8570-570157015701', 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Pernahkah LED berkedip tidak stabil, speaker amplifier mengeluarkan bunyi dengung, atau mikrokontroler reset sendiri tanpa sebab jelas? Tiga gejala ini punya tersangka utama yang sama: tidak adanya kapasitor yang tepat pada titik yang tepat. Kapasitor adalah komponen yang sering diremehkan pemula, padahal hampir tidak ada rangkaian elektronik modern yang bisa bekerja andal tanpanya.$txt$)),
(gen_random_uuid(), 'e5700001-5701-4570-8570-570157015701', 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Apa Itu Kapasitor$txt$)),
(gen_random_uuid(), 'e5700001-5701-4570-8570-570157015701', 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kapasitor terdiri dari dua pelat konduktor yang dipisahkan bahan isolator (dielektrik). Ia menyimpan muatan listrik dan melepaskannya saat dibutuhkan, seperti tandon air kecil untuk arus listrik. Kapasitasnya diukur dalam farad (F); yang umum dipakai adalah mikrofarad (µF) dan nanofarad (nF). Rumus dasarnya Q = C × V (muatan = kapasitansi × tegangan), dan energi yang tersimpan E = ½ × C × V². Dua keluarga besar kapasitor: elektrolit (kapasitas besar, punya polaritas positif-negatif) dan keramik/film (kapasitas kecil, tanpa polaritas, untuk frekuensi tinggi).$txt$)),
(gen_random_uuid(), 'e5700001-5701-4570-8570-570157015701', 'HEADING', 4, jsonb_build_object('text', $txt$Alat dan Bahan yang Dibutuhkan$txt$)),
(gen_random_uuid(), 'e5700001-5701-4570-8570-570157015701', 'LIST', 5, jsonb_build_object('items', ARRAY[$t$Kapasitor elektrolit 100 µF / 25 V (2 buah)$t$, $t$Kapasitor keramik 100 nF kode 104 (2 buah)$t$, $t$Breadboard dan kabel jumper$t$, $t$Multimeter digital$t$, $t$LED + resistor 220 ohm$t$, $t$Baterai 9 V dengan konektor$t$]::text[])),
(gen_random_uuid(), 'e5700001-5701-4570-8570-570157015701', 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: Memahami dan Memakai Kapasitor$txt$)),
(gen_random_uuid(), 'e5700001-5701-4570-8570-570157015701', 'LIST', 7, jsonb_build_object('items', ARRAY[$t$Baca nilai kapasitor: elektrolit tertulis langsung (mis. 100 µF), keramik memakai kode angka (104 berarti 10 × 10^4 pF = 100 nF).$t$, $t$Kenali polaritas: kaki panjang elektrolit adalah positif; ada garis strip di sisi negatif bodinya. Keramik tidak punya polaritas.$t$, $t$Uji isi-kosong sederhana: set multimeter ke ohm, tempelkan probe ke kaki kapasitor — angka naik lalu turun menunjukkan kapasitor mengisi dan sehat.$t$, $t$Pasang kapasitor decoupling 100 nF sedekat mungkin dengan kaki VCC dan GND IC/mikrokontroler untuk menyerap gangguan frekuensi tinggi.$t$, $t$Pasang kapasitor elektrolit 100 µF sejajar dengan jalur catu daya untuk meratakan tegangan (smoothing) — kaki positif ke jalur positif.$t$, $t$Nyalakan rangkaian dan amati: LED harus menyala stabil, tidak ada dengung, dan mikrokontroler tidak reset sendiri.$t$, $t$Hitung kebutuhan kasar: untuk penyearah sederhana, tiap 1 ampere arus butuh sekitar 1000–2000 µF agar riak tegangan kecil.$t$]::text[])),
(gen_random_uuid(), 'e5700001-5701-4570-8570-570157015701', 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Keselamatan$txt$)),
(gen_random_uuid(), 'e5700001-5701-4570-8570-570157015701', 'WARNING', 9, jsonb_build_object('text', $txt$Kapasitor elektrolit yang dipasang terbalik atau diberi tegangan melebihi batasnya bisa meledak dan menyemburkan cairan panas. Kapasitor berkapasitas besar menyimpan muatan berbahaya bahkan setelah listrik dimatikan — kosongkan dulu dengan menghubungkan resistor 1k ohm di kakinya sebelum disentuh. Jangan sekali-kali menyentuh kaki kapasitor pada rangkaian yang terhubung ke listrik PLN.$txt$)),
(gen_random_uuid(), 'e5700001-5701-4570-8570-570157015701', 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil$txt$)),
(gen_random_uuid(), 'e5700001-5701-4570-8570-570157015701', 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Periksa dengan checklist ini: tegangan catu daya stabil saat diukur multimeter (tidak naik-turun), tidak ada dengung pada audio, LED menyala konstan, dan mikrokontroler berjalan tanpa reset misterius. Jika semua terpenuhi, kapasitor Anda bekerja dengan benar. Tindak lanjut: pelajari filter RC untuk nada audio, dan rancang catu daya teregulasi dengan penyearah + kapasitor + regulator 7805.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
(gen_random_uuid(), 'e5700002-5702-4570-8570-570257025702', 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Kuah Rawon Tidak Hitam Pekat$txt$)),
(gen_random_uuid(), 'e5700002-5702-4570-8570-570257025702', 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Rawon yang enak punya tiga ciri: kuah hitam pekat, aroma kluwek yang khas, dan daging empuk. Kegagalan paling umum di dapur rumahan adalah kuah yang pucat kecokelatan, rasa pahit yang mengganggu, atau daging yang alot. Ketiganya bisa dihindari jika memahami satu bahan kunci: kluwek. Artikel ini memandu Anda membuat rawon otentik ala Jawa Timur dari nol.$txt$)),
(gen_random_uuid(), 'e5700002-5702-4570-8570-570257025702', 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Rahasia Kluwek$txt$)),
(gen_random_uuid(), 'e5700002-5702-4570-8570-570257025702', 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kluwek (Pangium edule) adalah biji buah kepayang yang difermentasi. Daging buahnya yang hitam inilah pewarna sekaligus pemberi rasa gurih-pahit khas rawon. Pilih kluwek yang berat dan padat saat dikocok tidak berbunyi kopong — itu tanda daging buahnya penuh. Kluwek yang kopong atau berjamur akan membuat kuah pahit dan tengik. Rendam kluwek dalam air panas 15 menit agar mudah dikeruk, lalu ambil daging buahnya dan haluskan bersama bumbu.$txt$)),
(gen_random_uuid(), 'e5700002-5702-4570-8570-570257025702', 'HEADING', 4, jsonb_build_object('text', $txt$Bahan-bahan (6 porsi)$txt$)),
(gen_random_uuid(), 'e5700002-5702-4570-8570-570257025702', 'LIST', 5, jsonb_build_object('items', ARRAY[$t$Daging sapi sandung lamur 500 gram, potong dadu 3 cm$t$, $t$Kluwek 5 butir, pilih yang padat$t$, $t$Bawang merah 8 siung, bawang putih 5 siung$t$, $t$Kemiri sangrai 4 butir, ketumbar 1 sdt, kunyit 2 cm$t$, $t$Lengkuas 3 cm (geprek), serai 2 batang (geprek)$t$, $t$Daun jeruk 4 lembar, garam 1,5 sdt, gula merah 1 sdm$t$, $t$Air 1,5 liter, minyak untuk menumis$t$]::text[])),
(gen_random_uuid(), 'e5700002-5702-4570-8570-570257025702', 'HEADING', 6, jsonb_build_object('text', $txt$Langkah Memasak$txt$)),
(gen_random_uuid(), 'e5700002-5702-4570-8570-570257025702', 'LIST', 7, jsonb_build_object('items', ARRAY[$t$Rebus daging dalam air mendidih 5 menit, buang air rebusan pertama untuk menghilangkan bau dan kotoran, lalu rebus kembali dengan 1,5 liter air bersih.$t$, $t$Keruk daging kluwek, haluskan bersama bawang merah, bawang putih, kemiri, ketumbar, dan kunyit hingga benar-benar halus.$t$, $t$Tumis bumbu halus dengan lengkuas, serai, dan daun jeruk hingga harum dan berminyak (sekitar 7 menit) — ini kunci kuah tidak langu.$t$, $t$Masukkan tumisan bumbu ke rebusan daging, aduk rata.$t$, $t$Masak dengan api kecil 1,5–2 jam hingga daging empuk dan kuah menyusut pekat. Jangan memakai api besar agar kuah tidak keruh.$t$, $t$Bumbui garam dan gula merah, koreksi rasa: gurih dulu, manis tipis, tanpa pahit menyengat.$t$, $t$Angkat serai dan lengkuas sebelum disajikan.$t$]::text[])),
(gen_random_uuid(), 'e5700002-5702-4570-8570-570257025702', 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Tips Penyelamatan$txt$)),
(gen_random_uuid(), 'e5700002-5702-4570-8570-570257025702', 'LIST', 9, jsonb_build_object('items', ARRAY[$t$Kuah pahit: hampir pasti dari kluwek kopong. Lain kali kocok dan pilih yang berat; rendam air panas sebelum dipakai.$t$, $t$Kuah keruh: api terlalu besar atau terlalu sering diaduk. Kecilkan api, aduk seperlunya saja.$t$, $t$Daging alot: potong melawan arah serat sejak awal, atau gunakan panci presto 30 menit setelah bumbu masuk.$t$]::text[])),
(gen_random_uuid(), 'e5700002-5702-4570-8570-570257025702', 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil$txt$)),
(gen_random_uuid(), 'e5700002-5702-4570-8570-570257025702', 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Rawon berhasil jika kuahnya hitam pekat dan sedikit berminyak di permukaan, daging empuk ditusuk garpu, dan aromanya gurih khas kluwek tanpa bau tengik. Sajikan panas dengan nasi putih, tauge pendek mentah, telur asin, sambal terasi, dan kerupuk udang. Sisa rawon tahan 3 hari di kulkas — panaskan hingga mendidih benar sebelum disajikan ulang, dan rasanya justru makin meresap keesokan harinya.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
(gen_random_uuid(), 'e5700003-5703-4570-8570-570357035703', 'HEADING', 0, jsonb_build_object('text', $txt$Satu Molekul, Sejuta Keajaiban$txt$)),
(gen_random_uuid(), 'e5700003-5703-4570-8570-570357035703', 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Air menutupi 71 persen permukaan Bumi dan menyusun sekitar 60 persen tubuh manusia dewasa. Rumus kimianya sederhana — H2O, dua atom hidrogen dan satu atom oksigen — tetapi perilakunya dipenuhi keanehan yang justru memungkinkan kehidupan. Tanpa keanehan-keanehan itu, Bumi mungkin planet mati.$txt$)),
(gen_random_uuid(), 'e5700003-5703-4570-8570-570357035703', 'HEADING', 2, jsonb_build_object('text', $txt$Struktur: Bengkok yang Sempurna$txt$)),
(gen_random_uuid(), 'e5700003-5703-4570-8570-570357035703', 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Molekul air tidak lurus, melainkan bengkok dengan sudut 104,5 derajat. Oksigen menarik elektron lebih kuat daripada hidrogen, sehingga molekul air bersifat polar: sisi oksigen sedikit negatif, sisi hidrogen sedikit positif. Kepolaran ini membuat molekul-molekul air saling menarik lewat ikatan hidrogen — ikatan lemah yang jumlahnya sangat banyak, sehingga efek kolektifnya luar biasa kuat. Ikatan hidrogen inilah sumber hampir semua keajaiban air.$txt$)),
(gen_random_uuid(), 'e5700003-5703-4570-8570-570357035703', 'HEADING', 4, jsonb_build_object('text', $txt$Sifat-sifat Aneh Air$txt$)),
(gen_random_uuid(), 'e5700003-5703-4570-8570-570357035703', 'LIST', 5, jsonb_build_object('items', ARRAY[$t$Es mengapung: air memuai saat membeku sehingga es lebih ringan dari air cair. Danau membeku dari permukaan ke bawah, dan makhluk air selamat di bawah lapisan es.$t$, $t$Kalor jenis tertinggi: air butuh banyak energi untuk naik suhunya, sehingga laut menjadi penstabil iklim Bumi dan tubuh kita tidak mudah demam panas.$t$, $t$Tegangan permukaan tinggi: serangga kecil bisa berjalan di atas air, dan tetesan air berbentuk bulat sempurna.$t$, $t$Kapilaritas: air naik melawan gravitasi di pipa sempit — cara tumbuhan mengangkut air dari akar ke daun tertinggi.$t$, $t$Pelarut universal: air melarutkan lebih banyak zat daripada cairan lain, menjadikannya medium seluruh reaksi kimia kehidupan.$t$]::text[])),
(gen_random_uuid(), 'e5700003-5703-4570-8570-570357035703', 'HEADING', 6, jsonb_build_object('text', $txt$Air dan Kehidupan$txt$)),
(gen_random_uuid(), 'e5700003-5703-4570-8570-570357035703', 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Fotosintesis memecah air untuk melepaskan oksigen yang kita hirup. Darah — yang 90 persennya air — mengangkut nutrisi dan oksigen ke seluruh tubuh. Di dalam sel, air adalah panggung tempat protein melipat, enzim bekerja, dan DNA menyimpan informasi. Para ilmuwan mencari kehidupan di planet lain dengan strategi sederhana: ikuti airnya (follow the water).$txt$)),
(gen_random_uuid(), 'e5700003-5703-4570-8570-570357035703', 'HEADING', 8, jsonb_build_object('text', $txt$Siklus Tanpa Henti$txt$)),
(gen_random_uuid(), 'e5700003-5703-4570-8570-570357035703', 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Air yang Anda minum hari ini mungkin pernah menjadi es di zaman dinosaurus. Ia menguap dari laut, mengembun menjadi awan, jatuh sebagai hujan, meresap ke tanah, mengalir lewat sungai, dan kembali ke laut — siklus yang sama selama miliaran tahun. Jumlah air di Bumi praktis tetap; yang berubah hanya distribusinya. Karena itu setiap tetes yang kita hemat berarti menjaga siklus raksasa ini tetap berjalan untuk generasi berikutnya.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
(gen_random_uuid(), 'e5700004-5704-4570-8570-570457045704', 'HEADING', 0, jsonb_build_object('text', $txt$Lahir dari Krisis 1965–1966$txt$)),
(gen_random_uuid(), 'e5700004-5704-4570-8570-570457045704', 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Orde Baru lahir dari pergolakan politik pascaperistiwa 30 September 1965. Melalui Surat Perintah 11 Maret 1966 (Supersemar), Soeharto — saat itu Panglima Angkatan Darat — menerima wewenang memulihkan keamanan, lalu secara bertahap mengambil alih kendali negara dari Soekarno. Pada 1967 Soeharto diangkat menjadi Pejabat Presiden, dan pada 1968 menjadi Presiden definitif. Istilah Orde Baru sendiri dipakai untuk menegaskan pemutusan dengan Orde Lama yang dinilai gagal.$txt$)),
(gen_random_uuid(), 'e5700004-5704-4570-8570-570457045704', 'HEADING', 2, jsonb_build_object('text', $txt$Konsolidasi Kekuasaan$txt$)),
(gen_random_uuid(), 'e5700004-5704-4570-8570-570457045704', 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Pemerintahan baru membangun stabilitas lewat kontrol politik yang ketat: konsep Dwifungsi ABRI menempatkan militer dalam jabatan sipil, Golkar dijadikan kendaraan politik pemerintah, dan partai-partai difusikan pada 1973 menjadi hanya dua — PPP dan PDI. Pemilu diselenggarakan enam kali (1971, 1977, 1982, 1987, 1992, 1997) dengan kemenangan Golkar yang selalu mutlak, dan Soeharto terpilih kembali oleh MPR dalam setiap Sidang Umum.$txt$)),
(gen_random_uuid(), 'e5700004-5704-4570-8570-570457045704', 'HEADING', 4, jsonb_build_object('text', $txt$Pembangunan Ekonomi$txt$)),
(gen_random_uuid(), 'e5700004-5704-4570-8570-570457045704', 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Sisi yang paling dikenang dari era ini adalah pembangunan ekonomi terencana lewat Repelita (Rencana Pembangunan Lima Tahun). Indonesia mencapai swasembada beras pada 1984, angka kemiskinan turun drastis, dan infrastruktur — jalan, sekolah Inpres, puskesmas — menjangkau pelosok. Namun pertumbuhan ini ditopang utang luar negeri yang membengkak, ketergantungan pada minyak, dan konglomerasi yang dekat dengan kekuasaan, sehingga fondasinya rapuh ketika krisis datang.$txt$)),
(gen_random_uuid(), 'e5700004-5704-4570-8570-570457045704', 'HEADING', 6, jsonb_build_object('text', $txt$Stabilitas dengan Tangan Besi$txt$)),
(gen_random_uuid(), 'e5700004-5704-4570-8570-570457045704', 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Stabilitas Orde Baru ditegakkan dengan pembatasan keras terhadap kebebasan: pers dibredel bila kritis, organisasi diawasi, dan setiap gejolak ditindak tegas — dari peristiwa Malari 1974, Tanjung Priok 1984, hingga operasi militer di Timor Timur, Aceh, dan Papua. Pendekatan keamanan ini memang meredam konflik terbuka selama tiga dekade, tetapi menumpuk kekecewaan yang tak tersalurkan lewat jalur demokratis.$txt$)),
(gen_random_uuid(), 'e5700004-5704-4570-8570-570457045704', 'HEADING', 8, jsonb_build_object('text', $txt$Krisis dan Kejatuhan 1997–1998$txt$)),
(gen_random_uuid(), 'e5700004-5704-4570-8570-570457045704', 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Krisis moneter Asia 1997 menghantam rupiah hingga kehilangan lebih dari 80 persen nilainya, harga-harga melonjak, dan jutaan orang kehilangan pekerjaan. Gerakan mahasiswa menuntut reformasi membesar, puncaknya pada tragedi Trisakti dan kerusuhan Mei 1998. Pada 21 Mei 1998 Soeharto mengundurkan diri setelah 32 tahun berkuasa, menyerahkan jabatan kepada Wakil Presiden B.J. Habibie. Era Reformasi pun dimulai — menutup bab terpanjang kekuasaan satu orang dalam sejarah Indonesia modern, dan membuka pelajaran abadi tentang bahaya kekuasaan tanpa batas waktu.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
(gen_random_uuid(), 'e5700005-5705-4570-8570-570557055705', 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$)),
(gen_random_uuid(), 'e5700005-5705-4570-8570-570557055705', 'LIST', 1, jsonb_build_object('items', ARRAY[$t$Menjelaskan pengertian nilai sosial dan norma sosial.$t$, $t$Mengidentifikasi ciri-ciri dan fungsi nilai sosial dalam masyarakat.$t$, $t$Membedakan empat tingkatan norma sosial beserta contohnya.$t$, $t$Menganalisis pelanggaran norma dalam kehidupan sehari-hari.$t$]::text[])),
(gen_random_uuid(), 'e5700005-5705-4570-8570-570557055705', 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian Nilai Sosial$txt$)),
(gen_random_uuid(), 'e5700005-5705-4570-8570-570557055705', 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Nilai sosial adalah anggapan masyarakat tentang sesuatu yang dianggap baik, buruk, pantas, atau tidak pantas. Nilai bersifat abstrak — ia tidak bisa dilihat, tetapi menuntun perilaku. Contoh: masyarakat Indonesia menjunjung nilai gotong royong, kejujuran, dan penghormatan kepada orang tua. Nilai berbeda antar masyarakat: apa yang dianggap sopan di satu daerah bisa dianggap aneh di daerah lain, karena nilai lahir dari kesepakatan dan pengalaman kolektif suatu kelompok.$txt$)),
(gen_random_uuid(), 'e5700005-5705-4570-8570-570557055705', 'HEADING', 4, jsonb_build_object('text', $txt$Ciri-ciri dan Fungsi Nilai Sosial$txt$)),
(gen_random_uuid(), 'e5700005-5705-4570-8570-570557055705', 'LIST', 5, jsonb_build_object('items', ARRAY[$t$Terbentuk melalui interaksi sosial yang panjang, bukan bawaan lahir.$t$, $t$Disebarkan lewat sosialisasi: keluarga, sekolah, dan lingkungan.$t$, $t$Berfungsi sebagai pedoman perilaku dan alat pemersatu masyarakat.$t$, $t$Berfungsi sebagai pengawas: pelanggaran nilai menimbulkan rasa malu atau celaan sosial.$t$]::text[])),
(gen_random_uuid(), 'e5700005-5705-4570-8570-570557055705', 'HEADING', 6, jsonb_build_object('text', $txt$Pengertian Norma Sosial$txt$)),
(gen_random_uuid(), 'e5700005-5705-4570-8570-570557055705', 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Jika nilai adalah cita-cita abstrak, norma adalah aturan konkretnya. Norma sosial adalah kaidah atau ketentuan yang mengatur perilaku anggota masyarakat, lengkap dengan sanksi bagi pelanggarnya. Contoh: nilai kebersihan diwujudkan dalam norma dilarang membuang sampah sembarangan — pelanggarnya bisa ditegur atau didenda. Tanpa norma, nilai hanya menjadi slogan tanpa daya ikat.$txt$)),
(gen_random_uuid(), 'e5700005-5705-4570-8570-570557055705', 'HEADING', 8, jsonb_build_object('text', $txt$Empat Tingkatan Norma Sosial$txt$)),
(gen_random_uuid(), 'e5700005-5705-4570-8570-570557055705', 'LIST', 9, jsonb_build_object('items', ARRAY[$t$Cara (usage): tata cara ringan sehari-hari, mis. cara memegang sendok. Sanksi: sekadar dianggap aneh.$t$, $t$Kebiasaan (folkways): perbuatan berulang yang menjadi kebiasaan, mis. memberi salam saat bertemu. Sanksi: teguran ringan.$t$, $t$Tata kelakuan (mores): norma yang menyangkut moral, mis. larangan berbohong dan mencuri. Sanksi: dikucilkan masyarakat.$t$, $t$Adat istiadat (custom): tata kelakuan yang mengakar kuat dan turun-temurun, mis. upacara adat perkawinan. Sanksi: sangat berat, bisa diusir dari komunitas.$t$]::text[])),
(gen_random_uuid(), 'e5700005-5705-4570-8570-570557055705', 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal$txt$)),
(gen_random_uuid(), 'e5700005-5705-4570-8570-570557055705', 'LIST', 11, jsonb_build_object('items', ARRAY[$t$Jelaskan perbedaan nilai sosial dan norma sosial dengan contoh masing-masing!$t$, $t$Sebutkan empat tingkatan norma sosial beserta satu contoh dan sanksinya!$t$, $t$Mengapa pelanggaran tata kelakuan (mores) sanksinya lebih berat daripada pelanggaran cara (usage)? Jelaskan!$t$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
(gen_random_uuid(), 'e5700006-5706-4570-8570-570657065706', 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$)),
(gen_random_uuid(), 'e5700006-5706-4570-8570-570657065706', 'LIST', 1, jsonb_build_object('items', ARRAY[$t$Menjelaskan pengertian shalat dan kedudukannya dalam Islam.$t$, $t$Menyebutkan syarat wajib dan syarat sah shalat.$t$, $t$Menyebutkan rukun-rukun shalat secara berurutan.$t$, $t$Mempraktikkan gerakan shalat dengan tertib.$t$]::text[])),
(gen_random_uuid(), 'e5700006-5706-4570-8570-570657065706', 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian Shalat$txt$)),
(gen_random_uuid(), 'e5700006-5706-4570-8570-570657065706', 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Shalat adalah ibadah yang terdiri dari perkataan dan perbuatan tertentu, diawali dengan takbiratul ihram dan diakhiri dengan salam. Shalat merupakan rukun Islam yang kedua setelah syahadat, dan hukumnya wajib bagi setiap muslim yang sudah baligh dan berakal. Shalat lima waktu — Subuh, Zuhur, Asar, Magrib, dan Isya — adalah tiang agama: siapa menegakkannya berarti menegakkan agama.$txt$)),
(gen_random_uuid(), 'e5700006-5706-4570-8570-570657065706', 'HEADING', 4, jsonb_build_object('text', $txt$Syarat Wajib dan Syarat Sah Shalat$txt$)),
(gen_random_uuid(), 'e5700006-5706-4570-8570-570657065706', 'LIST', 5, jsonb_build_object('items', ARRAY[$t$Syarat wajib: beragama Islam, sudah baligh, dan berakal sehat.$t$, $t$Syarat sah: suci dari hadas dan najis (berwudu), menutup aurat, menghadap kiblat, sudah masuk waktu shalat, dan mengetahui tata cara shalat.$t$]::text[])),
(gen_random_uuid(), 'e5700006-5706-4570-8570-570657065706', 'HEADING', 6, jsonb_build_object('text', $txt$Rukun-rukun Shalat$txt$)),
(gen_random_uuid(), 'e5700006-5706-4570-8570-570657065706', 'LIST', 7, jsonb_build_object('items', ARRAY[$t$Niat di dalam hati$t$, $t$Takbiratul ihram (mengucap Allahu Akbar)$t$, $t$Berdiri tegak bagi yang mampu$t$, $t$Membaca Surah Al-Fatihah$t$, $t$Rukuk dengan tumaninah$t$, $t$Iktidal (bangkit dari rukuk) dengan tumaninah$t$, $t$Sujud dua kali dengan tumaninah$t$, $t$Duduk di antara dua sujud dengan tumaninah$t$, $t$Duduk tasyahud akhir$t$, $t$Membaca tasyahud akhir$t$, $t$Membaca salawat atas Nabi Muhammad$t$, $t$Mengucap salam pertama$t$, $t$Tertib: mengerjakan rukun secara berurutan$t$]::text[])),
(gen_random_uuid(), 'e5700006-5706-4570-8570-570657065706', 'HEADING', 8, jsonb_build_object('text', $txt$Gerakan dan Bacaan Pokok$txt$)),
(gen_random_uuid(), 'e5700006-5706-4570-8570-570657065706', 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Urutan gerakan shalat: berdiri tegak menghadap kiblat — takbiratul ihram sambil mengangkat kedua tangan — bersedekap membaca doa iftitah lalu Al-Fatihah dan surah pendek — rukuk sambil membaca tasbih — iktidal — sujud — duduk di antara dua sujud — sujud kedua — bangkit ke rakaat berikutnya — duduk tasyahud akhir — salam ke kanan dan ke kiri. Tumaninah artinya tenang dan tidak terburu-buru di setiap gerakan. Latihlah bacaan Al-Fatihah hingga lancar karena ia wajib dibaca di setiap rakaat.$txt$)),
(gen_random_uuid(), 'e5700006-5706-4570-8570-570657065706', 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal$txt$)),
(gen_random_uuid(), 'e5700006-5706-4570-8570-570657065706', 'LIST', 11, jsonb_build_object('items', ARRAY[$t$Apa pengertian shalat? Sebutkan rukun Islam yang keberapa!$t$, $t$Sebutkan tiga syarat sah shalat!$t$, $t$Urutkan gerakan shalat dari takbiratul ihram sampai salam!$t$, $t$Kunci: (1) Ibadah perkataan dan perbuatan diawali takbir diakhiri salam; rukun Islam kedua. (2) Contoh: suci dari hadas/najis, menutup aurat, menghadap kiblat, masuk waktu, tahu tata caranya. (3) Takbiratul ihram – berdiri – Al-Fatihah – rukuk – iktidal – sujud – duduk di antara dua sujud – sujud kedua – tasyahud akhir – salam.$t$]::text[]));
